import os, json, re

session_file = '/home/USER/runs/paper/qwen-h0c1-card/frozen/held-out-reference-4/play/users/u071/system/state/sessions/01a18a0f-20dd-7526-81a9-dffcd123a365.jsonl'

with open(session_file, 'r') as f:
    lines = f.readlines()

print("=== Comprehensive Demo Search ===\n")

# Check each assistant message for potential grid content
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)

        if msg.get('type') == 'message' and msg['message'].get('role') == 'assistant':
            full_content = ""

            # From thinking blocks
            if 'thinking' in msg['message']['content']:
                full_content += msg['message']['content'][0].get('thinking', '')

            # From text blocks  
            content_items = msg['message']['content']
            for item in content_items:
                if isinstance(item, dict):
                    k = list(item.keys())[0]
                    v = item.get(k, '')
                    if isinstance(v, str):
                        full_content += v

            # Look for "[[grid]]" or similar patterns indicating demo output
            if '[[' in full_content or re.search(r'\d+\[\d+\]', full_content):
                print(f"\n=== Assistant Message {i} has potential grid content ===")

                # Extract any 2D array-like sections
                # Look for sections that look like grids
                if 'Demo' in full_content:
                    # Show where Demo appears
                    demo_idx = full_content.find('Demo')
                    context = full_content[demo_idx:demo_idx+300]
                    print(f"Context around 'Demo':\n{context}")

    except Exception as e:
        pass

# Also check for tool results that might have grid data
print("\n\n=== Checking Tool Results for grids ===")
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        if msg.get('type') == 'message' and msg.get('toolName'):
            tool_result = msg['message'].get('content', [])
            for item in tool_result:
                if isinstance(item, dict):
                    txt = item.get('text', '')
                    if re.search(r'^\d+\s+\d+', txt, re.MULTILINE):
                        print(f"\n=== Tool Result {i} ({msg['message']['toolCallId']}): {msg['message']['toolName']} ===")
                        print(txt[:500])
    except:
        pass

